    Section {
        LabeledContent("Base URL") {
            TextField(provider.defaultBaseURL, text: baseURLBinding(for: provider))
                .textFieldStyle(.roundedBorder)
                .frame(maxWidth: 240)
                #if os(iOS)
                .autocorrectionDisabled()
                .textInputAutocapitalization(.never)
                #endif
        }

